<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Disable\SnippetAssetDisableUsecase;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Batch\SnippetAssetTaskDisable;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\MagicLinkService;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Disable\SnippetAssetDisableResult;

class SnippetAssetDisableController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Runner $runner,
        private readonly SqlTemplate $sql,
        private readonly SnippetAssetDisableUsecase $disableUsecase,
        private readonly Context $context,
        private readonly MagicLinkService $links,
    ) {
    }
    #[OA\Patch(
        path: "/api/document/snippet-asset/{uid}/disable",
        tags: ["Snippet asset"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetAssetApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
    ]
    )
    ]
    public function disable(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("disable for Snippet asset");
        $span = $this->startSpan("disable for Snippet asset");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->disableUsecase->disable($uid);
            $this->sql->commit();
            $value = $this->mapSnippetAsset($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }
    public function disableAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("disable all for query Snippet asset");
        $span = $this->startSpan("disable all for query Snippet asset");
        try {
            $params = $request->getQueryParams();
            $filter = new SnippetAssetFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                code: $params['code'] ?? null,
                snippet: isset($params['snippet']) ? new SnippetRef($params['snippet']) : null,
                snippets: isset($params['snippets']) ? explode(",", $params['snippets']) : null,
            );
            $res = $this->runner->run(SnippetAssetTaskDisable::class, ['filter' => $filter]);
            $encoded = json_encode($res);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function checkDisableAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check disable all for query Snippet asset");
        $span = $this->startSpan("Check disable all for query Snippet asset");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $info = $this->runner->detail(new TaskKey($uid));
            if (!$info) {
                throw new NotFoundException('-');
            }
            $encoded = json_encode($info);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapSnippetAsset(ServerRequestInterface $request, SnippetAssetDisableResult $value): SnippetAssetApiDTO
    {
        $this->logDebug("Map entity to output dto for Snippet asset");
        $span = $this->startSpan("Map entity to output dto for Snippet asset");
        try {
            $snippet = $value->getSnippet();
            $dto = new SnippetAssetApiDTO();
            $dto->uid = $value->getUid();
            $dto->snippet = $snippet ? ['$ref' => $snippet->uid()] : null;
            $dto->code = $value->getCode();
            $dto->type = $value->getType();
            if (null !== $value->getContent()) {
                $url = $this->context->getBaseUrl() . '/api/document/snippet-asset/' . ($value->getUid() ?? '-'). '/content';
                $dto->content = $this->links->create($url, $request);
            }
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
